package mux

import (
	"net/http"
	"testing"
)

// Hidden F2P regression test (ADR-0032.1 S4). Two same-path routes that differ
// only by query constraints: a request matching the second must match cleanly.
func TestGHXMultipleQueriesSamePath(t *testing.T) {
	emptyHandler := func(w http.ResponseWriter, r *http.Request) {}
	r := NewRouter()
	r.HandleFunc("/api", emptyHandler).Queries("foo", "{foo:[0-9]+}").Methods(http.MethodGet)
	r.HandleFunc("/api", emptyHandler).Queries("bar", "{bar:[0-9]+}").Methods(http.MethodGet)
	req, _ := http.NewRequest(http.MethodGet, "http://localhost/api?bar=4", nil)
	match := new(RouteMatch)
	if !r.Match(req, match) {
		t.Fatal("should have matched second query route")
	}
	if match.MatchErr != nil {
		t.Fatalf("MatchErr should be nil, got %v", match.MatchErr)
	}
}
GHXEOF
